TLM.f("Sancti/08-06",{"officium":"In Transfiguratione Domini Nostri Jesu Christi","rule":["Gloria","Credo","Prefatio=Communis","Prefatio=Nat","Festum Domini"],"sections":{"Introitus":[{"k":"ref","la":"Ps 76:19"},{"k":"text","la":"Illuxérunt coruscatiónes tuæ orbi terræ: commóta est et contrémuit terra."},{"k":"ref","la":"Ps 83:2-3"},{"k":"text","la":"Quam dilécta tabernácula tua, Dómine virtútum! concupíscit, et déficit ánima mea in átria Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Illuxérunt coruscatiónes tuæ orbi terræ: commóta est et contrémuit terra."}],"Oratio":[{"k":"text","la":"Deus, qui fídei sacraménta in Unigéniti tui gloriósa Transfiguratióne patrum testimónio roborásti, et adoptiónem filiórum perféctam, voce delápsa in nube lúcida, mirabíliter præsignásti: concéde propítius; ut ipsíus Regis glóriæ nos coherédes effícias, et ejúsdem glóriæ tríbuas esse consórtes."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"2 Petri 1:16-19"},{"k":"text","la":"Caríssimi: Non doctas fábulas secúti notam fecimus vobis Dómini nostri Jesu Christi virtútem et præséntiam: sed speculatores facti illíus magnitudinis. Accipiens enim a Deo Patre honórem et glóriam, voce delapsa ad eum hujuscemodi a magnifica glória: Hic est Fílius meus diléctus, in quo mihi complacui, ipsum audíte. Et hanc vocem nos audivimus de cœlo allatam, cum essemus cum ipso in monte sancto. Et habémus firmiórem propheticum sermónem: cui bene facitis attendentes, quasi lucérnæ lucénti in caliginóso loco, donec dies elucescat et lucifer oriátur in córdibus vestris."}],"Graduale":[{"k":"ref","la":"Ps 44:3; 44:2"},{"k":"text","la":"Speciosus forma præ fíliis hóminum: diffúsa est grátia in lábiis tuis."},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 7:26"},{"k":"text","la":"Candor est lucis ætérnæ, spéculum sine mácula, et imágo bonitátis illíus. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 17:1-9"},{"k":"text","la":"In illo témpore: Assúmpsit Jesus Petrum, et Jacóbum, et Joánnem fratrem ejus, et duxit illos in montem excélsum seórsum: et transfigurátus est ante eos. Et resplénduit fácies ejus sicut sol: vestiménta autem ejus facta sunt alba sicut nix. Et ecce, apparuérunt illis Moyses et Elías cum eo loquéntes. Respóndens autem Petrus, dixit ad Jesum: Dómine, bonum est nos hic esse: si vis, faciámus hic tria tabernácula, tibi unum, Móysi unum et Elíæ unum. Adhuc eo loquénte, ecce, nubes lúcida obumbrávit eos. Et ecce vox de nube, dicens: Hic est Fílius meus diléctus, in quo mihi bene complácui: ipsum audíte. Et audiéntes discípuli, cecidérunt in fáciem suam, et timuérunt valde. Et accéssit Jesus, et tétigit eos, dixítque eis: Surgite, et nolíte timére. Levántes autem óculos suos, néminem vidérunt nisi solum Jesum. Et descendéntibus illis de monte, præcépit eis Jesus, dicens: Némini dixéritis visiónem, donec Fílius hóminis a mórtuis resúrgat."}],"Offertorium":[{"k":"ref","la":"Ps 111:3"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi, allelúja."}],"Secreta":[{"k":"text","la":"Obláta, quǽsumus, Dómine, múnera gloriósa Unigéniti tui Transfiguratióne sanctífica: nosque a peccatórum máculis, splendóribus ipsíus illustratiónis emúnda."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Matt 17:9"},{"k":"text","la":"Visiónem, quam vidístis, némini dixéritis, donec a mórtuis resúrgat Fílius hóminis."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut sacrosáncta Fílii tui Transfiguratiónis mystéria, quæ sollemni celebrámus offício, purificáta mentis intellegéntia consequámur."},{"k":"macro","name":"Per eundem"}]},"hr":{"029a4b8b29430c56":{"t":"Ps 76, 19, Ps 83, 2-3\n(Ps 76, 19) Tvoje su munje rasvijetlile zemaljski krug, potresla se i uzdrhtala zemlja. (Ps 83, 2-3) Kako su mili stanovi tvoji, Gospodine vojska! Duša moja čeznu i gine za dvorovima Gospodnjim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 76, 19) Tvoje su munje rasvijetlile zemaljski krug, potresla se i uzdrhtala zemlja."},"cbb6746dafca45f2":{"t":"<i>Pomolimo se</i>.\nBože, koji si pri slavnom preobraženju svoga Jedinorođenca otajstva vjere potvrdio po svjedočanstvu otaca i divno unaprijed označio savršeno posinovljenje glasom iz svijetla oblaka, podaj milostivo da nas učiniš subaštinicima istoga Kralja slave i dadeš da budemo sudionici iste slave.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8cac7424cce40824":{"t":"2 Pt 1, 16-19\nČitanje Poslanice bl. Petra apostola. Predragi, objavili smo vam silu i dolazak našega Gospodina Isusa Krista, ne kao da smo zavedeni izmišljenim bajkama, nego jer smo sami bili očevici njegova veličanstva. On je primio čast i slavu od Boga Oca, kad mu je od one uzvišene slave došao ovaj glas: Ovo je moj ljubljeni Sin koji mi je po volji, slušajte ga! I taj glas, što dođe s neba, mi smo čuli, kad smo bili s njim na svetoj gori. Tako imamo još više potvrđeno proroštvo, i dobro činite što se ravnate po njemu kao po svjetiljci koja svijetli u tamnome mjestu, dok ne osvane dan, i dok se ne pomoli danica u vašim srcima."},"bcf7961f54259739":{"t":"Ps 44, 3 i 2\nLjepši si od svih sinova ljudskih, milina je razlivena na tvojim usnama. Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju.\n\nMudr 7, 26\n<i>Aleluja</i>, <i>aleluja</i>.\nOdsjev je vječnog svjetla, zrcalo bez ljage, slika njegove dobrote. <i>Aleluja</i>."},"47598764b5506c06":{"t":"Mt 17, 1-9\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: uze Isus sa sobom Petra, Jakova i njegova brata Ivana, i povede ih nasamo na visoku goru te se preobrazi pred njima. Njegovo lice zasja kao sunce, a haljine mu pobijeliše kao snijeg. I gle, ukažu im se Mojsije i Ilija razgovarajući s njim. Tada Petar reče Isusu: Gospodine, dobro nam je ovdje. Ako hoćeš, ovdje ćemo podići tri sjenice: jednu tebi, jednu Mojsiju, jednu Iliji. Dok je on još govorio, prekrije ih svijetao oblak. I gle, iz oblaka se čuo glas: Ovo je moj ljubljeni Sin koji mi je po volji, njega slušajte! – Kad su to učenici čuli, padnu ničice silno prestrašeni. Isus im pristupi, dotače ih se i reče: Ustanite i ne bojte se! Oni podignu oči i ne vidješe nikoga, osim Isusa. I dok su silazili s gore, Isus im naloži: Ne govorite nikome o viđenju, dok Sin Čovječji ne uskrsne od mrtvih.","v":"et → ∅"},"4b3d1a7d826bc67c":{"t":"Ps 111, 3\nSlava i bogatstvo bit će u domu njegovu, njegova će pravda trajati u vijeke, <i>aleluja</i>."},"917c68c7f5f572db":{"t":"Prinesene darove, molimo, Gospodine, posveti slavnim preobraženjem svoga Jedinorođenca, a nas od ljage grijeha očisti sjajem njegova svjetla.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"8e9ee5dc90b6e81a":{"t":"Mt 17, 9\nNe govorite nikome o viđenju, dok Sin čovječji ne uskrsne od mrtvih."},"1b46418f73034df7":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da očišćene duše shvatimo otajstva preobraženja tvoga Sina, koje slavimo svečanom službom.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:"}}});
